const fs = require('fs');
const path = require('path');
const vmm = require('vm');
const SRC = JSON.parse(fs.readFileSync(path.join(__dirname, 'src_g4_science_u4.json'), 'utf8'));
const OUT = path.join(__dirname, '..', 'data', 'g4_science_u4.js');
const DIR = '4단원_다양한생물과우리생활';
